import {Run,WORLD} from './core.mjs?v=2';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),$=id=>document.getElementById(id);
const run=new Run();const W=WORLD.width,H=WORLD.height,ground=WORLD.ground;
let cssW=720,cssH=420,scale=1,offsetY=0,dpr=1,last=null,t=0,travel=0,stock=0,muted=true,audio,particles=[],catchTime=0,resultShown=false,best=0,toastUntil=0,toast='',storageOK=true;
try{const n=Number(localStorage.getItem('patat-best'));if(Number.isFinite(n)&&n>=0)best=n}catch{storageOK=false}
$('best').innerHTML=best+' <i>m</i>';
function resize(){const r=canvas.getBoundingClientRect();cssW=r.width;cssH=r.height;dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(cssW*dpr);canvas.height=Math.round(cssH*dpr);scale=cssW/W;offsetY=cssH-29-H*scale;draw()}
new ResizeObserver(resize).observe(canvas);
function sound(freq=500,d=.08){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
function burst(x,y,color,n=7){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*170,vy:-Math.random()*130,life:.55,color})}
function hideCoach(){$('coach').classList.add('hidden')}
function coach(title,text){$('coach-title').textContent=title;$('coach-text').textContent=text;$('coach').classList.remove('hidden')}
function start(){run.start();particles=[];catchTime=0;resultShown=false;last=null;toastUntil=0;$('overlay').classList.add('hidden');$('result').classList.add('hidden');$('pause').disabled=false;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pauzeren');updateHud();$('start').blur()}
function show(title,message,button){$('title').textContent=title;$('message').textContent=message;$('start').textContent=button;$('overlay').classList.remove('hidden');hideCoach()}
function pause(){if(run.state==='playing'){run.pause();clearHeld();$('stamp').textContent='EVEN UITWAAIEN';show('Even uitwaaien.','Je frietjes lopen niet weg.','VERDER SPELEN →');$('hint').textContent='Druk op P, Escape of de knop om verder te gaan.';$('pause').textContent='▶';$('pause').setAttribute('aria-label','Hervatten')}else if(run.state==='paused'){run.resume();last=null;$('overlay').classList.add('hidden');$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pauzeren')}}
function finish(){resultShown=true;const score=run.distance,isRecord=score>best;if(isRecord){best=score;try{localStorage.setItem('patat-best',String(best))}catch{storageOK=false}}$('best').innerHTML=best+' <i>m</i>';$('stamp').textContent=isRecord?'NIEUW PERSOONLIJK RECORD':'DE FRIET IS TERUG';show('PATATSTELLING.',run.hit?.kind==='umbrella'?'Die parasol hing laag. Houd Buk ingedrukt om eronderdoor te gaan.':'Die koelbox stond in de weg. Spring iets eerder om hem te ontwijken.','NOG EEN PORTIE →');$('result').innerHTML='<span><b>'+score+'</b>meter gevlucht</span><span><b>'+run.collected+'</b>frietjes gepikt</span>';$('result').classList.remove('hidden');$('hint').textContent='Een nieuwe poging begint meteen. Je record blijft bewaard.';$('pause').disabled=true;updateSaveNote()}
function updateSaveNote(){$('save-note').textContent=storageOK?'Je record blijft op dit apparaat bewaard.':'Je browser kan het record niet bewaren. Deze sessie kun je wel gewoon spelen.'}updateSaveNote();
function updateHud(){$('distance').innerHTML=run.distance+' <i>m</i>';$('fries').innerHTML=run.stock+' <i>/ 12</i>';$('weight').textContent=run.stock>=9?'Volle snavel · lagere sprong':run.stock>=5?'Stevige buit':'Lichte buit';$('weight').classList.toggle('full',run.stock>=9);$('flap').setAttribute('aria-label',`Fladder, kost één frietje. ${run.stock} beschikbaar.`);$('status').textContent=run.stock>=9?'VOLLE SNAVEL? FLADDER VOOR EXTRA HOOGTE':run.stock>0?'FLADDER KOST 1 FRIETJE · JE WORDT WEER LICHTER':'PAK FRIETJES VOOR EXTRA VLEUGELSLAGEN'}
function prompts(){if(run.state!=='playing'){hideCoach();return}if(t<1.8){coach('HÉ! MIJN PATAT!','De snackbarhouder zit achter je aan.');return}if(toastUntil>t){coach(toast,run.stock?'Je voorraad staat bovenin.':'Pak eerst een frietje om te fladderen.');return}const next=run.obstacles.find(o=>!o.passed&&o.worldX-travel>WORLD.birdX-40);if(next&&next.worldX-travel<WORLD.birdX+390&&run.distance<210){coach(next.kind==='umbrella'?'↓ BUK ONDER DE PARASOL':'↑ SPRING OVER DE KOELBOX',next.kind==='umbrella'?'Houd Buk ingedrukt tot je er voorbij bent.':'Tik op Spring of gebruik de spatiebalk.');return}if(run.stock>=9){coach('VOLLE SNAVEL = ZWAARDER','Fladder verbruikt 1 frietje en geeft extra hoogte.');return}if(run.distance>65&&run.distance<95){coach('✦ FRIET IS JE BRANDSTOF','Tik op Fladder, ook tijdens een sprong.');return}hideCoach()}
function round(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}function ellipse(x,y,rx,ry,c){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}function line(x,y,a,b,c,width=2){ctx.strokeStyle=c;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(a,b);ctx.stroke()}function poly(points,c){ctx.fillStyle=c;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill()}
function gull(x,y,scale=1){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);const crouch=run.crouching,flapping=run.y<ground-4,leg=Math.sin(t*22)*5;ellipse(0,1,25,5,'#163e4220');line(-7,-5,-11+(flapping?0:leg),0,'#d78537',4);line(8,-5,14-(flapping?0:leg),0,'#d78537',4);ellipse(0,crouch?-17:-25,27,crouch?13:21,'#fffdf1');poly([[-21,-22],[-39,-31],[-30,-12]],'#e3e8dd');ellipse(-3,crouch?-18:-27,17,flapping?5:12,'#b2c7c8');if(flapping){poly([[-16,-25],[-20,-52-Math.sin(t*20)*9],[10,-25]],'#b2c7c8')}ellipse(20,crouch?-24:-43,16,17,'#fffdf1');poly([[30,crouch?-28:-45],[49,crouch?-22:-39],[30,crouch?-19:-34]],'#f7ae31');ellipse(24,crouch?-28:-47,3,3,'#153e42');line(19,crouch?-34:-53,29,crouch?-31:-52,'#153e42',2);if(stock){line(39,crouch?-20:-36,49,crouch?-8:-24,'#ffc84b',5)}ctx.restore()}
function background(){ctx.fillStyle='#bce1df';ctx.fillRect(0,0,W,H);ellipse(W*.8,96,34,34,'#fff1ad');for(let i=0;i<5;i++){let x=((i*280-travel*.08)%(W+300)+W+300)%(W+300)-100;ellipse(x,90+i%2*35,45,10,'#e9f5e9');ellipse(x+20,84+i%2*35,25,15,'#e9f5e9')}ctx.fillStyle='#70b7bc';ctx.fillRect(0,ground-145,W,120);for(let i=0;i<12;i++){let x=(i*150-travel*.2)%(W+150);line(x,ground-120+i%3*20,x+60,ground-120+i%3*20,'#b5d9d1',2)}ctx.fillStyle='#e9d7ac';ctx.fillRect(0,ground-70,W,70);for(let i=0;i<6;i++){let x=((i*210-travel*.35)%(W+250)+W+250)%(W+250)-140;let y=ground-100;round(x,y,60,60,3,i%2?'#e6a08a':'#6e9c96');poly([[x-5,y],[x+30,y-25],[x+65,y]],'#fff3db');round(x+22,y+24,17,36,2,'#426e70');line(x+7,y+5,x+7,y+55,'#ffffff50');line(x+51,y+5,x+51,y+55,'#ffffff50')}line(0,ground-24,W,ground-24,'#6e8880',5);for(let x=-travel*.8%85;x<W;x+=85)line(x,ground-25,x,ground-50,'#6e8880',4);line(0,ground-50,W,ground-50,'#6e8880',3);ctx.fillStyle='#e6b689';ctx.fillRect(0,ground,W,H-ground);ctx.fillStyle='#f5cca0';ctx.fillRect(0,ground,W,8);for(let i=0;i<3;i++){let y=ground+10+i*24;line(0,y,W,y,'#cb986d',1);for(let x=-travel%(100)+(i%2)*50;x<W;x+=100)line(x,y,x,y+24,'#cb986d',1)}}
function obstacle(source){const o={...source,x:source.worldX-travel};if(o.kind==='umbrella'){ctx.save();ctx.translate(0,20);line(o.x+o.w+17,ground-20,o.x+o.w+17,ground-76,'#88a69d',3);poly([[o.x-8,ground-65],[o.x+o.w/2,ground-130],[o.x+o.w+8,ground-65]],'#ef795a');poly([[o.x+o.w*.2,ground-65],[o.x+o.w/2,ground-130],[o.x+o.w*.7,ground-65]],'#fff0c9');round(o.x-8,ground-68,o.w+16,8,4,'#cf5b40');ctx.restore()}else{round(o.x,ground-o.h,o.w,o.h,5,'#4b8d92');round(o.x-3,ground-o.h,o.w+6,9,3,'#f5f0dc');round(o.x+o.w/2-8,ground-o.h+17,16,9,3,'#f7c658');line(o.x+7,ground-4,o.x+o.w-7,ground-4,'#34727c',3)}}
function chef(x,y,catching=false){const stride=Math.sin(t*15),bounce=Math.abs(stride)*3;ctx.save();ctx.translate(x,y-bounce);ellipse(0,1,24,5,'#163e4220');line(-8,-4,-15-stride*10,1,'#153e42',6);line(6,-4,16+stride*10,1,'#153e42',6);round(-16,-48,31,43,9,'#ef795a');round(-12,-40,25,32,3,'#fff2d6');line(-14,-41,-23-stride*6,-24,'#ecb889',6);line(14,-41,29+(catching?15:0),-44+(catching?-6:stride*7),'#ecb889',6);ellipse(1,-61,16,17,'#ecb889');round(-17,-80,35,10,3,'#fffdf1');ellipse(-9,-82,10,9,'#fffdf1');ellipse(4,-85,11,10,'#fffdf1');ellipse(15,-81,9,8,'#fffdf1');ellipse(9,-64,2,2,'#153e42');line(3,-70,13,-73,'#153e42',2);line(8,-52,17,-54,'#153e42',2);poly([[14,-49],[17,-53],[20,-48]],'#ffffff');ctx.restore()}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#bce1df';ctx.fillRect(0,0,cssW,cssH);ctx.save();ctx.translate(0,offsetY);ctx.scale(scale,scale);t=run.time+catchTime;travel=run.travel;stock=run.stock;background();for(const f of run.foods){const x=f.worldX-travel;ctx.save();ctx.translate(x,f.y);ctx.rotate(.2);round(-4,-10,8,20,2,'#ffe27a');round(-4,-10,3,20,1,'#f5b53f');ctx.restore()}run.obstacles.forEach(obstacle);chef(39+Math.min(1,catchTime/.6)*59,ground,run.state==='caught');if(run.state==='caught'){ctx.save();ctx.translate(WORLD.birdX,run.y);ctx.rotate(Math.min(catchTime*3,.5));gull(0,0);ctx.restore();if(run.hit){const q=run.obstacleBox(run.hit);ctx.strokeStyle='#ed6445';ctx.lineWidth=3;ctx.setLineDash([5,4]);ctx.strokeRect(q.x-3,q.y-3,q.w+6,q.h+6);ctx.setLineDash([])}}else gull(WORLD.birdX,run.y);for(const p of particles){ctx.globalAlpha=Math.max(0,p.life*1.8);round(p.x,p.y,5,5,1,p.color)}ctx.globalAlpha=1;ctx.restore()}
function events(){for(const e of run.takeEvents()){if(e.kind==='pickup'){burst(e.x,e.y,'#ffcf4d');sound(820,.045)}if(e.kind==='flap'){burst(e.x,e.y,'#fffaf0',10);sound(620,.09)}if(e.kind==='jump')sound(420,.06);if(e.kind==='empty'){toast='JE SNAVEL IS LEEG';toastUntil=t+1.6}if(e.kind==='hit'){burst(WORLD.birdX,run.y-20,'#f8d897',14);sound(140,.3);$('pause').disabled=true;clearHeld()}if(e.kind==='stall'){run.state='playing';pause();$('message').textContent='Even gepauzeerd omdat het spel kort vastliep. Je poging blijft bewaard.'}}}
function frame(now){const dt=last===null?0:Math.max(0,(now-last)/1000);last=now;if(run.state==='playing')run.advance(dt);events();if(run.state==='caught'&&!resultShown){catchTime+=Math.min(dt,.05);if(catchTime>.7)finish()}if(run.state==='playing'||run.state==='caught'){for(const p of particles){p.x+=p.vx*Math.min(dt,.05);p.y+=p.vy*Math.min(dt,.05);p.vy+=400*Math.min(dt,.05);p.life-=Math.min(dt,.05)}particles=particles.filter(p=>p.life>0)}updateHud();prompts();draw();requestAnimationFrame(frame)}
function clearHeld(){run.setDuck(false);$('duck').classList.remove('pressed');$('duck').setAttribute('aria-pressed','false')}
$('start').onclick=()=>run.state==='paused'?pause():start();$('pause').onclick=pause;$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'Geluid uit':'Geluid aan';$('sound').setAttribute('aria-pressed',String(!muted));sound()};
for(const [id,action] of [['jump',()=>run.jump()],['flap',()=>run.flap()]]){$(id).addEventListener('pointerdown',e=>{e.preventDefault();action()});$(id).addEventListener('click',e=>{if(e.detail===0)action()})}
$('duck').addEventListener('pointerdown',e=>{e.preventDefault();if(run.state!=='playing')return;run.setDuck(true);$('duck').classList.add('pressed');$('duck').setAttribute('aria-pressed','true');$('duck').setPointerCapture(e.pointerId)});for(const event of ['pointerup','pointercancel','lostpointercapture'])$('duck').addEventListener(event,clearHeld);
$('duck').addEventListener('keydown',e=>{if(['Space','Enter'].includes(e.code)){e.preventDefault();if(run.state==='playing'){run.setDuck(true);$('duck').classList.add('pressed');$('duck').setAttribute('aria-pressed','true')}}});$('duck').addEventListener('keyup',e=>{if(['Space','Enter'].includes(e.code)){e.preventDefault();clearHeld()}});$('duck').addEventListener('blur',clearHeld);
window.addEventListener('keydown',e=>{if(e.target instanceof HTMLElement&&e.target.matches('button,a,input,textarea,select'))return;if(['Space','ArrowUp','ArrowDown','KeyF','KeyP','Escape'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Space'||e.code==='ArrowUp')run.jump();if(e.code==='ArrowDown'){run.setDuck(true);$('duck').classList.add('pressed')}if(e.code==='KeyF')run.flap();if(e.code==='KeyP'||e.code==='Escape')pause()});window.addEventListener('keyup',e=>{if(e.code==='ArrowDown')clearHeld()});window.addEventListener('blur',()=>{clearHeld();if(run.state==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&run.state==='playing')pause()});requestAnimationFrame(frame);
